-- ===== U10 vocab 覆盖灌库(volume='9',39词)。分步跑。=====

SELECT 'U10 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U10';

DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U10';
SELECT 'U10 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U10';  -- 应0


SELECT 'U10 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U10';  -- 应39
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U10' GROUP BY word HAVING count(*)>1;  -- 查重应0行